// Android en Argentina, octubre de 2026 (StatCounter, móviles y tabletas), en % del tráfico web medido.
// [versión, nivel de API, %]  (agrupé 12 y 12.3 en el nivel 31; 5.1, 5.0 y 4.4 en el 21)
const datos = [
  ["Android 17", 37, 0.93], ["Android 16", 36, 31.59], ["Android 15", 35, 15.78],
  ["Android 14", 34, 19.46], ["Android 13", 33, 13.88], ["Android 12", 31, 7.58],
  ["Android 11", 30, 5.85], ["Android 10", 29, 1.65], ["Android 9", 28, 1.21],
  ["Android 8.1", 27, 0.96], ["Android 8.0", 26, 0.26], ["Android 7.1", 25, 0.13],
  ["Android 7.0", 24, 0.13], ["Android 6.0", 23, 0.36], ["Android 5.x y 4.4", 21, 0.19],
];

function cobertura(minSdk) {
  return datos.filter(([, api]) => api >= minSdk).reduce((s, [, , p]) => s + p, 0);
}

console.log("minSdk -> % de teléfonos que podrían instalar la app");
for (const m of [21, 23, 24, 26, 29, 31, 33, 34, 35, 36]) {
  console.log(`  ${String(m).padStart(2)} -> ${cobertura(m).toFixed(2)} %`);
}

// De píxeles reales a dp: dp = px / (dpi / 160)
function aDp(px, dpi) { return px / (dpi / 160); }
console.log("\nUna pantalla de 1080 x 2400 píxeles a 420 dpi (ejemplo):");
console.log(`  ancho = ${aDp(1080, 420).toFixed(1)} dp, alto = ${aDp(2400, 420).toFixed(1)} dp`);
console.log("El mismo diseño de 360 dp de ancho, en píxeles según la densidad:");
for (const [nombre, dpi] of [["mdpi", 160], ["hdpi", 240], ["xhdpi", 320], ["xxhdpi", 480], ["xxxhdpi", 640]]) {
  console.log(`  ${nombre.padEnd(8)} (${dpi} dpi): ${360 * dpi / 160} px`);
}
